uniform float low_ammo : hint_range(0.0, 1.0) = 0.0;
uniform vec4 warning_color : source_color = vec4(1.0, 0.188, 0.188, 1.0);

void fragment() {
	// The label's theme drop shadow is drawn through this same CanvasItem in
	// pure black; leave it black (CHANGE-BRIEF revision 2026-10-29).
	float glyph = step(0.004, max(COLOR.r, max(COLOR.g, COLOR.b)));
	COLOR.rgb = mix(COLOR.rgb, warning_color.rgb, low_ammo * glyph);

func _on_ammo_changed(mag: int, _reserve: int) -> void:
	target = 1.0 if mag <= THRESHOLD else 0.0


func _process(delta: float) -> void:
	if value == target:
		return
	# Moves from wherever it is, so a retrigger extends (R4, R7).
	value = move_toward(value, target, (RATE_UP if target > value else RATE_DOWN) * delta)
	material.set_shader_parameter(PARAM, value)

